param()
$ErrorActionPreference='Stop'
Add-Type -AssemblyName PresentationCore,PresentationFramework,WindowsBase
$materialRoot=Split-Path -Parent $PSScriptRoot
$report=Get-Content -LiteralPath (Join-Path $materialRoot 'artifacts/material-lab/release-verification/material-test-results.json') -Raw -Encoding UTF8|ConvertFrom-Json
function Read-MaterialImage([string]$relative){$stream=[IO.File]::OpenRead((Join-Path $materialRoot $relative));try{$bitmap=[Windows.Media.Imaging.BitmapImage]::new();$bitmap.BeginInit();$bitmap.CacheOption='OnLoad';$bitmap.StreamSource=$stream;$bitmap.EndInit();$bitmap.Freeze();return $bitmap}finally{$stream.Dispose()}}
function Label($dc,[string]$label,[double]$x,[double]$y){$t=[Windows.Media.FormattedText]::new($label,[Globalization.CultureInfo]::GetCultureInfo('zh-CN'),[Windows.FlowDirection]::LeftToRight,[Windows.Media.Typeface]::new('Microsoft YaHei UI'),16,[Windows.Media.Brushes]::Black,1.0);$dc.DrawText($t,[Windows.Point]::new($x,$y))}
function Save-Comparison($visual,[int]$width,[int]$height,[string]$file){$b=[Windows.Media.Imaging.RenderTargetBitmap]::new($width,$height,96,96,[Windows.Media.PixelFormats]::Pbgra32);$b.Render($visual);$e=[Windows.Media.Imaging.PngBitmapEncoder]::new();$e.Frames.Add([Windows.Media.Imaging.BitmapFrame]::Create($b));$s=[IO.File]::Create((Join-Path $materialRoot ('artifacts/material-lab/'+$file)));try{$e.Save($s)}finally{$s.Dispose()}}
function Actual-Crop([string]$name,[string]$part){$frame=$report.frames|Where-Object {$_.name -eq $name};$bounds=$frame.$part;$scale=$frame.scale;$b=Read-MaterialImage ('artifacts/material-lab/release-verification/'+$name+'.png');return [Windows.Media.Imaging.CroppedBitmap]::new($b,[Windows.Int32Rect]::new([int][Math]::Round($bounds.x*$scale),[int][Math]::Round($bounds.y*$scale),[int][Math]::Round($bounds.width*$scale),[int][Math]::Round($bounds.height*$scale)))}
$reference=Read-MaterialImage 'design/ui/轻透主题/01-暖香槟-默认.png'
$source=[Windows.Media.Imaging.CroppedBitmap]::new($reference,[Windows.Int32Rect]::new(52,122,1004,820))
$actual=Actual-Crop '01-warm-home' 'stage'
$v=[Windows.Media.DrawingVisual]::new();$c=$v.RenderOpen();$c.DrawRectangle([Windows.Media.Brushes]::White,$null,[Windows.Rect]::new(0,0,2072,930));Label $c '已选效果图 · 首页' 24 16;Label $c '原生材质样板 · 暖色 / 3 条启用 / 固定演示时刻' 1060 16;$c.DrawImage($source,[Windows.Rect]::new(24,56,1004,820));$c.DrawImage($actual,[Windows.Rect]::new(1060,56,1004,1004*$actual.PixelHeight/$actual.PixelWidth));Label $c '移除样板工具栏后按宽度归一，保持比例；不据此宣称逐像素一致。' 24 895;$c.Close();Save-Comparison $v 2072 930 '01-reference-home-comparison.png'
$source=[Windows.Media.Imaging.CroppedBitmap]::new($reference,[Windows.Int32Rect]::new(1088,263,406,587));$actual=Actual-Crop '14-transmission-contrast' 'dialog'
$v=[Windows.Media.DrawingVisual]::new();$c=$v.RenderOpen();$c.DrawRectangle([Windows.Media.Brushes]::White,$null,[Windows.Rect]::new(0,0,924,730));Label $c '已选效果图 · 独立提醒' 24 16;Label $c '原生任务层 · 透射测试' 488 16;$c.DrawImage($source,[Windows.Rect]::new(24,56,406,587));$c.DrawImage($actual,[Windows.Rect]::new(488,56,406,406*$actual.PixelHeight/$actual.PixelWidth));Label $c '背景与长宽比例不同，原生样板另有返回预览动作；比较材质、边界与光影。' 24 682;$c.Close();Save-Comparison $v 924 730 '02-reference-task-comparison.png'
Write-Output 'Native material comparisons rendered.'
